};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    scwin.gDepCd = js_dep_cd;

    //  기간 from~ to  셋팅
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue($c.ut.cGetMinusDate2(vCurDate, 7));
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    // dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    const sbmOptions = {
        id : "sbm_dts_dep",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_dep=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)
    const sbmOptions2 = {
        id : "sbm_dts_emp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_emp=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions3 = {
        id : "sbm_dts_Indp",
        action : "/ListedSearch.do",
        ref : "",
        target : "dts_Indp=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    //+"\n/"+
    // alert("rdo_FEE_TP_CD"+"\n/"+InfoMenuID()+"\n/"+js_id+"\n/"+js_dep_cd+"\n/"+getObjectValue(rdo_FEE_TP_CD));

    // 수수료구분코드 rdo_FEE_TP_CD
    /*if (("999999" == js_id)) { // 시스템관리1
    	setObjectValue(rdo_FEE_TP_CD, "A");
    } else if (("2500" == js_dep_cd) || ("3300" == js_dep_cd)) { // 상장총괄
    	setObjectValue(rdo_FEE_TP_CD, "1");
    } else if (InfoMenuID() == "STF03705") { // 상장수수료화면
    	setObjectValue(rdo_FEE_TP_CD, "2");
    } else if (InfoMenuID() == "STF03706") { // 연부과금화면
    } else if (InfoMenuID() == "STF03706") { // 연부과금화면
    	setObjectValue(rdo_FEE_TP_CD, "3");
    } else {
    	setObjectValue(rdo_FEE_TP_CD, "A");
    }*/

    if (("999999" === js_id)) {
        // 시스템관리1
        if ($c.cm.InfoMenuID() === "STF03705") {
            // 상장수수료
