    }
};

/**
     * @method
     * @name listSync
     * @description list Sync 처리
     * @returns {Promise<void>}
     * @hidden N
     */
scwin.listSync = async function() {
    let feeTpCd;
    if (("999999" === js_id)) {
        // 시스템관리1
        if ($c.cm.InfoMenuID() === "STF03705") {
            // 상장수수료
            feeTpCd = "A5";
        } else if ($c.cm.InfoMenuID() === "STF03706") {
            // 연부과금
            feeTpCd = "A6";
        }
    } else {
        feeTpCd = rdo_FEE_TP_CD.getValue();
    }
    url += "&SDATE=" + $c.ut.cGetMinusDate2(edt_SDate.getValue(), -1);
    url += "&EDATE=" + edt_EDate.getValue();
    url += "&PAY_PROCS_STAT_CD=" + rdo_PAY_PROCS_STAT_CD.getValue();
    url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    url += "&TEAMLIST=" + cmb_TeamList.BindColVal;
    url += "&EMPLIST=" + cmb_EmpList.BindColVal;
    url += "&MARKET_TP_CD=" + rdo_MARKET_TP_CD.getValue();
    url += "&FEE_TP_CD=" + feeTpCd;
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/ListFeeAnulFee.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name saveUpdate
 * @description save Update 처리
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveUpdate = async function(colid) {
    const res = window.confirm("확인 저장 하겠습니까?");
    if (res) {
        url += "&ADJ_PAY_AMT=" + dts_List.getCellData(dts_List.getRowPosition(), 'ADJ_PAY_AMT');
        url += "&LST_PAY_AMT=" + dts_List.getCellData(dts_List.getRowPosition(), 'LST_PAY_AMT');
        url += "&PAY_PROCS_STAT_CD=" + dts_List.getCellData(dts_List.getRowPosition(), 'PAY_PROCS_STAT_CD');
        url += "&TRANSTR_EMP_NO=" + js_id;
        url += "&RCV_DD=" + dts_List.getCellData(dts_List.getRowPosition(), 'RCV_DD');
        url += "&SEQ=" + dts_List.getCellData(dts_List.getRowPosition(), 'SEQ');
        const sbmOptions = {
            id : "sbm_dts_parameter",
            action : "/ListFeeAnulFee.do",
            ref : "",
            target : "dts_parameter=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        await scwin.listSync();
    } else {
        dts_List.undoRow(colid);
    }
};

/**
 * @method
 * @name saveBatchupdate
 * @description save Batchupdate 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.saveBatchupdate = async function() {
    if (dts_List.getRowCount() === 0) {
        await $c.win.alert("수정대상이 없습니다.");
        return;
    }
    let gStat;
    let gStatCnt = 0;
    dts_List.setBroadcast(false);
    for (let k = 1; k <= dts_List.getRowCount(); k++) {
        gStat = dts_List.getRowStatus(k);
        if (gStat === TB_JOB_UPDATE) {
            dts_List.setCellData(k, "TRANSTR_EMP_NO", js_id);
            gStatCnt++;
        }
    }
    dts_List.setBroadcast(true, true);
    if (gStatCnt === 0) {
        await $c.win.alert("수정대상이 없습니다.");
        return;
    }
    if (!window.confirm($c.stf.getMessageParam("MSG-A006", '총 ' + gStatCnt + '건을 저장'))) return;
    trs_Save.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/ListFeeAnulFee.do",
        ref : "dts_List",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

