/**
 * @method
 * @name setContnId
 * @description set Contn Id 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gIsurCd = dts_List.getCellData(Number(obj), "ISUR_CD");
};

/**
 * @method
 * @name calculation
 * @description calculation 처리
 * @returns {void}
 * @hidden N
 */
scwin.calculation = function() {
    let vPAY_AMT = 0;
    let vADJ_PAY_AMT = 0;
    let vLST_PAY_AMT = 0;
    vPAY_AMT = dts_List.getCellData(dts_List.getRowPosition(), 'PAY_AMT');
    vADJ_PAY_AMT = dts_List.getCellData(dts_List.getRowPosition(), 'ADJ_PAY_AMT');

    // alert("vPAY_AMT="+vPAY_AMT+"\n/"+vADJ_PAY_AMT+"\n/"+vADJ_PAY_AMT);
    // alert("eval(vPAY_AMT)="+eval(vPAY_AMT)+"\n/"+eval(vADJ_PAY_AMT)+"\n/"+eval(vADJ_PAY_AMT));

    vLST_PAY_AMT = Number(vPAY_AMT) + Number(vADJ_PAY_AMT);
    dts_List.setCellData(dts_List.getRowPosition(), 'LST_PAY_AMT', vLST_PAY_AMT);
};

/**
 * @method
 * @name calculationRowid
 * @description calculation Rowid 처리
 * @param {*} rowid rowid
 * @returns {void}
 * @hidden N
 */
scwin.calculationRowid = function(rowid) {
    let vPAY_AMT = 0;
    let vADJ_PAY_AMT = 0;
    let vLST_PAY_AMT = 0;
    vPAY_AMT = dts_List.getCellData(rowid, 'PAY_AMT');
    vADJ_PAY_AMT = dts_List.getCellData(rowid, 'ADJ_PAY_AMT');

    // alert("vPAY_AMT="+vPAY_AMT+"\n/"+vADJ_PAY_AMT+"\n/"+vADJ_PAY_AMT);
    // alert("eval(vPAY_AMT)="+eval(vPAY_AMT)+"\n/"+eval(vADJ_PAY_AMT)+"\n/"+eval(vADJ_PAY_AMT));

    vLST_PAY_AMT = Number(vPAY_AMT) + Number(vADJ_PAY_AMT);
    dts_List.setCellData(rowid, 'LST_PAY_AMT', vLST_PAY_AMT);
};

/**
 * @method
 * @name allUpdate
 * @description all Update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.allUpdate = async function() {
    const val = cmb_update.ValueOfIndex("VALUE", cmb_update.getSelectedIndex());
    // alert("cmb_update="+val);

    if (val !== '') {
        if (dts_List.getRowCount() === 0) {
            await $c.win.alert("업데이트 대상이  없습니다.");
            cmb_update.setValue('');
            return;
        }
        dts_List.setBroadcast(false);
        for (let k = 1; k <= dts_List.getRowCount(); k++) {
            if (dts_List.getCellData(k, 'PAY_PROCS_STAT_CD') === '2') {
                dts_List.setCellData(k, "PAY_PROCS_STAT_CD", val);
                scwin.calculationRowid(k);
            }
        }
        dts_List.setBroadcast(true);
    }
};
